@EnabledIfEnvironmentVariable(named="PLM_FOUNDATION_IT_URL",matches="jdbc:postgresql://127\\.0\\.0\\.1:15483/plm_foundation_crud_it\\?currentSchema=plm")
class InventoryCustomerLifecycleLocalIntegrationTest {
 final ObjectMapper json=new ObjectMapper().findAndRegisterModules();JdbcTemplate jdbc;DataSourceTransactionManager manager;TransactionStatus fixture;TransactionTemplate tx;PilotAccessService access;OperationLogService audit;PartnerStore store;InventoryMaintenanceService inventory;PartnerCustomerService customers;CurrentUser admin;
 @BeforeEach void setup(){var ds=new DriverManagerDataSource(System.getenv("PLM_FOUNDATION_IT_URL"),"postgres",System.getenv("PLM_FOUNDATION_IT_PASSWORD"));jdbc=new JdbcTemplate(ds);assertThat(jdbc.queryForObject("select current_database()",String.class)).isEqualTo("plm_foundation_crud_it");manager=new DataSourceTransactionManager(ds);fixture=manager.getTransaction(new DefaultTransactionDefinition());tx=new TransactionTemplate(manager);tx.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);var u=jdbc.queryForMap("select user_id,username,display_name from sys_user where all_permissions and status='active' and deleted_flag=0 order by user_id limit 1");admin=new CurrentUser(number(u.get("user_id")),text(u.get("username")),text(u.get("display_name")),true);CurrentUserContext.set(admin);access=new PilotAccessService(jdbc,json);audit=mock(OperationLogService.class);store=new PartnerStore(jdbc,json,access,audit);var refs=new FoundationObjectReferences(jdbc,json,access);inventory=new InventoryMaintenanceService(jdbc,json,access,audit,refs);customers=new PartnerCustomerService(store);ReflectionTestUtils.setField(customers,"references",refs);}
 @AfterEach void rollback(){try{if(fixture!=null&&!fixture.isCompleted())manager.rollback(fixture);}finally{CurrentUserContext.clear();}}
 Map<String,Object> material(){return new LinkedHashMap<>(Map.of("code","QA-FOUND-00"+UUID.randomUUID(),"name","隔离真实物料","unit","pcs","inventoryType","material","requestId",UUID.randomUUID().toString()));}
 Map<String,Object> action(long version){return Map.of("version",version,"requestId",UUID.randomUUID().toString(),"reason","隔离错建核对");}
 long createInventory(){return number(inventory.save(null,false,material()).get("id"));}
 long createCustomer(){return number(customers.save(null,new LinkedHashMap<>(Map.of("customerName","隔离客户 "+UUID.randomUUID(),"customerType","company","status","active","requestId",UUID.randomUUID().toString()))).get("customerId"));}
 long product(){return jdbc.queryForObject("insert into plm_product(product_code,product_name,product_type,version_no,status,development_mode,current_step_no,created_by,updated_by) values(?,'隔离引用项目','product_line','V1','draft','launch_v1',1,'foundation-it','foundation-it') returning product_id",Long.class,"QA-FOUND-P-"+UUID.randomUUID());}
 void event(long product,Map<String,Object> data){jdbc.update("insert into plm_product_development_event(product_id,kind,data,created_by) values(?,'foundation_it',?::jsonb,'foundation-it')",product,encode(json,data));}
 @Test void inventoryCreateIsDurableAcrossFreshServiceReloadAndRetryAndIgnoresClientQuantity(){var input=material();input.put("quantity",999);var saved=inventory.save(null,false,input);long id=number(saved.get("id"));assertThat(jdbc.queryForObject("select quantity from plm_inventory where inventory_id=?",java.math.BigDecimal.class,id)).isZero();assertThat(inventory.detail(id,false)).containsEntry("code",input.get("code")).containsEntry("unit","pcs");assertThat(number(inventory.save(null,false,input).get("id"))).isEqualTo(id);assertThat(jdbc.queryForObject("select count(*) from plm_inventory where inventory_code=?",Integer.class,input.get("code"))).isEqualTo(1);}
 @Test void inventoryEditKeepsQuantityAndOriginalCodeAndRejectsStaleVersion(){long id=createInventory();jdbc.update("update plm_inventory set quantity=7 where inventory_id=?",id);var edit=new LinkedHashMap<>(inventory.detail(id,false));edit.put("name","更正后的物料");edit.put("reason","更正拼写");edit.put("requestId",UUID.randomUUID().toString());edit.put("quantity",0);inventory.save(id,false,edit);assertThat(inventory.detail(id,false)).containsEntry("name","更正后的物料");assertThat(jdbc.queryForObject("select quantity from plm_inventory where inventory_id=?",java.math.BigDecimal.class,id)).isEqualByComparingTo("7");assertThat(number(inventory.save(id,false,edit).get("version"))).isEqualTo(2);edit.put("requestId",UUID.randomUUID().toString());assertThatThrownBy(()->inventory.save(id,false,edit)).isInstanceOfSatisfying(BusinessException.class,e->assertThat(e.getCode()).isEqualTo(40901));var check=inventory.inspect(id,false);assertThat(check).containsEntry("canDelete",false);assertThat(check.get("blockedReason")).asString().contains("库存余额");}
 @Test void unusedInventorySoftDeleteIsIdempotentAndCannotBeRecreatedOrResurrected(){var input=material();long id=number(inventory.save(null,false,input).get("id"));assertThat(inventory.inspect(id,false)).containsEntry("canDelete",true);var command=action(1);var removed=inventory.lifecycle(id,false,"delete",command);assertThat(removed).containsEntry("deleted",true);assertThat(number(inventory.lifecycle(id,false,"delete",command).get("version"))).isEqualTo(2);assertThatThrownBy(()->inventory.save(null,false,input)).hasMessageContaining("已删除");var fresh=new LinkedHashMap<>(input);fresh.put("requestId",UUID.randomUUID().toString());assertThatThrownBy(()->tx.execute(t->inventory.save(null,false,fresh))).hasMessageContaining("历史档案");assertThatThrownBy(()->tx.execute(t->{jdbc.update("update plm_inventory set deleted_flag=0 where inventory_id=?",id);return null;})).hasMessageContaining("不能由同步");}
 @Test void historyReferenceBlocksDeleteAndDeactivationKeepsOriginalHistoryReadable(){long id=createInventory(),p=product();event(p,Map.of("inventoryId",id));jdbc.update("update plm_product set deleted_flag=1 where product_id=?",p);var check=inventory.inspect(id,false);assertThat(check).containsEntry("canDelete",false);assertThat(check.toString()).contains("history=true");assertThatThrownBy(()->inventory.lifecycle(id,false,"delete",action(1))).hasMessageContaining("历史引用");inventory.lifecycle(id,false,"deactivate",action(1));assertThat(inventory.detail(id,false)).containsEntry("status","inactive");assertThatThrownBy(()->MasterDataAdoption.requireInventory(jdbc,id,null,null,null)).hasMessageContaining("已停用");MasterDataAdoption.requireInventory(jdbc,id,null,id,null);assertThat(jdbc.queryForObject("select count(*) from plm_product_development_event where product_id=?",Integer.class,p)).isEqualTo(1);inventory.lifecycle(id,false,"activate",action(2));MasterDataAdoption.requireInventory(jdbc,id,null,null,null);}
 @Test void materialGroupsPersistAndCannotDeleteReferencedItemsOrAcceptNewItemsAfterStop(){var group=inventory.save(null,true,Map.of("code","QA-FOUND-G-"+UUID.randomUUID(),"name","隔离材料组","requestId",UUID.randomUUID().toString()));long gid=number(group.get("id"));var input=material();input.put("groupId",gid);inventory.save(null,false,input);assertThat(inventory.groups()).anyMatch(g->number(g.get("id"))==gid);assertThat(inventory.inspect(gid,true)).containsEntry("canDelete",false);inventory.lifecycle(gid,true,"deactivate",action(1));var newer=material();newer.put("groupId",gid);assertThatThrownBy(()->inventory.save(null,false,newer)).hasMessageContaining("已停用");}
 @Test void readOnlyAccountCannotWriteInventoryEvenWithInventoryView(){long uid=scopedUser(List.of("inventory:view","product:view"),true);CurrentUserContext.set(new CurrentUser(uid,"foundation-view","隔离只读",false));assertThatThrownBy(()->inventory.save(null,false,material())).hasMessageContaining("权限");}
 long scopedUser(List<String> permissions,boolean all){String key=UUID.randomUUID().toString();long uid=jdbc.queryForObject("insert into sys_user(user_code,user_name,login_name,username,password_hash,status,display_name,department_name,all_permissions,created_by,updated_by) values(?,'隔离工程',?,?,'not-password','active','隔离工程','工程',false,'foundation-it','foundation-it') returning user_id",Long.class,"QA-FOUND-U-"+key,"found_"+key.substring(0,12),"found_"+key.substring(0,12));jdbc.update("insert into plm_pilot_account(user_id,role_code,permissions,all_objects,created_by,updated_by) values(?,'domestic',?::jsonb,?,'foundation-it','foundation-it')",uid,encode(json,permissions),all);return uid;}
 @Test void restrictedReferencesBlockDeletionWithoutLeakingNamesIdsOrCounts(){long id=createInventory(),p=product();event(p,Map.of("inventoryId",id));long uid=scopedUser(List.of("inventory:view","product:view"),false);CurrentUserContext.set(new CurrentUser(uid,"foundation-view","隔离只读",false));var check=inventory.inspect(id,false);assertThat(check).containsEntry("canDelete",false).containsEntry("hasRestrictedReferences",true);assertThat((List<?>)check.get("references")).isEmpty();assertThat(check.toString()).doesNotContain("隔离引用项目","QA-FOUND-P-");}
 @Test void requiredAuditFailureRollsBackInventoryCreation(){doThrow(new IllegalStateException("audit unavailable")).when(audit).logRequired(any(),any());var input=material();assertThatThrownBy(()->tx.execute(t->inventory.save(null,false,input))).hasMessageContaining("audit unavailable");assertThat(jdbc.queryForObject("select count(*) from plm_inventory where inventory_code=?",Integer.class,input.get("code"))).isZero();}
 @Test void customerUnusedDeleteAndStatusLifecycleRetainEventsWithoutSelfReference(){long id=createCustomer();assertThat(customers.references(id)).containsEntry("canDelete",true);var stopped=customers.lifecycle(id,"deactivate",action(1));assertThat(stopped).containsEntry("status","inactive");customers.lifecycle(id,"activate",action(2));assertThat(customers.references(id)).containsEntry("canDelete",true);var command=action(3);assertThat(customers.lifecycle(id,"delete",command)).containsEntry("deleted",true);assertThat(customers.lifecycle(id,"delete",command)).containsEntry("deleted",true);assertThat(jdbc.queryForObject("select count(*) from plm_partner_event where customer_id=?",Integer.class,id)).isEqualTo(4);}
 @Test void customerBusinessHistoryBlocksDeleteAndCanDeactivateWithoutChangingOriginalRecord(){long id=createCustomer();long record=store.create("sale","隔离客户历史");jdbc.update("update plm_partner_record set customer_id=?,deleted_flag=1 where record_id=?",id,record);String before=jdbc.queryForObject("select to_jsonb(p)::text from plm_partner_record p where record_id=?",String.class,record);assertThat(customers.references(id)).containsEntry("canDelete",false);assertThatThrownBy(()->customers.lifecycle(id,"delete",action(1))).hasMessageContaining("历史引用");customers.lifecycle(id,"deactivate",action(1));assertThat(jdbc.queryForObject("select to_jsonb(p)::text from plm_partner_record p where record_id=?",String.class,record)).isEqualTo(before);}
 @Test void inactiveCustomerCannotReceiveNewLoanButExistingLoanMayBeReturned(){long customer=createCustomer();var samples=new PartnerSampleService(store,mock(PartnerProductService.class),mock(PartnerMaterialService.class));var initial=new LinkedHashMap<String,Object>(Map.of("sourceType","self","pending",true,"provenance","隔离期初样","name","隔离样品","qty",3,"date","2026-10-25","location","工程","requestId",UUID.randomUUID().toString()));long sample=number(samples.create(initial).get("id"));var loan=new LinkedHashMap<String,Object>(Map.of("version",1,"requestId",UUID.randomUUID().toString(),"customerId",customer,"qty",1,"date","2026-10-25","due","2026-10-27","location","工程","refs",List.of()));var borrowed=samples.action(sample,"loan",loan);long loanId=number(maps(map(borrowed.get("balances")).get("loans")).get(0).get("id"));customers.lifecycle(customer,"deactivate",action(1));loan.put("version",2);loan.put("requestId",UUID.randomUUID().toString());assertThatThrownBy(()->samples.action(sample,"loan",loan)).hasMessageContaining("已停用");var returned=samples.action(sample,"return",Map.of("version",2,"requestId",UUID.randomUUID().toString(),"customerId",customer,"qty",1,"date","2026-10-26","location","工程","loanId",loanId,"refs",List.of()));assertThat(map(returned.get("balances"))).containsEntry("borrowed",0L);}
 @ParameterizedTest @ValueSource(booleans={true,false}) void inventoryDeleteAndAdoptionShareOneDatabaseLock(boolean writerFirst)throws Exception{
  manager.rollback(fixture);fixture=null;var independent=new TransactionTemplate(manager);long id=independent.execute(t->createInventory());long p=independent.execute(t->product());var held=new CountDownLatch(1);var release=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);
  try{Callable<Object> writer=()->{CurrentUserContext.set(admin);try{return independent.execute(t->{MasterDataAdoption.requireInventory(jdbc,id,null,null,null);if(writerFirst){held.countDown();await(release);}event(p,Map.of("inventoryId",id));return id;});}finally{CurrentUserContext.clear();}};Callable<Object> remover=()->{CurrentUserContext.set(admin);try{return independent.execute(t->{var result=inventory.lifecycle(id,false,"delete",action(1));if(!writerFirst){held.countDown();await(release);}return result;});}finally{CurrentUserContext.clear();}};var first=pool.submit(writerFirst?writer:remover);assertThat(held.await(5,TimeUnit.SECONDS)).isTrue();var second=pool.submit(writerFirst?remover:writer);Thread.sleep(200);assertThat(second.isDone()).isFalse();release.countDown();first.get(15,TimeUnit.SECONDS);assertThatThrownBy(()->second.get(15,TimeUnit.SECONDS)).hasCauseInstanceOf(BusinessException.class);
  }finally{release.countDown();pool.shutdownNow();pool.awaitTermination(10,TimeUnit.SECONDS);CurrentUserContext.set(admin);independent.execute(t->{jdbc.update("delete from plm_product_development_event where product_id=?",p);jdbc.update("delete from plm_product where product_id=?",p);jdbc.update("delete from plm_inventory where inventory_id=?",id);return null;});}
 }

 @ParameterizedTest @ValueSource(booleans={true,false}) void ownProductAssociationUsesRealVisibilityInsteadOfUnconditionalRestrictedFlag(boolean visible){long id=createInventory(),p=product();jdbc.update("update plm_inventory set product_id=? where inventory_id=?",p,id);if(!visible){long uid=scopedUser(List.of("inventory:view","product:view"),false);CurrentUserContext.set(new CurrentUser(uid,"foundation-view","隔离只读",false));}var check=inventory.inspect(id,false);assertThat(check).containsEntry("canDelete",false).containsEntry("hasRestrictedReferences",!visible);if(visible){assertThat(check.toString()).contains("所属产品","隔离引用项目","QA-FOUND-P-");}else{assertThat((List<?>)check.get("references")).isEmpty();assertThat(check.toString()).doesNotContain("隔离引用项目","QA-FOUND-P-");}}
 @Test void mesSourceNameIsExplicitlyReadonlyWhileLocalSpecAndRemarkRemainEditable(){long id=createInventory();jdbc.update("insert into plm_master_data_source(source_system,organization_id,source_kind,source_id,object_type,object_id,source_code,source_hash,source_data,observed_at,batch_hash) values('mes','foundation-it','material_items',?,'inventory',?,'QA-MES',repeat('a',64),'{}',now(),repeat('b',64))",UUID.randomUUID().toString(),id);var actual=inventory.detail(id,false);assertThat(actual).containsEntry("sourceNameReadonly",true).containsEntry("sourceSystem","MES");var input=new LinkedHashMap<>(actual);input.put("requestId",UUID.randomUUID().toString());input.put("reason","补充本地说明");input.put("spec","本地补充规格");input.put("remark","本地补充备注");var saved=inventory.save(id,false,input);assertThat(saved).containsEntry("spec","本地补充规格").containsEntry("remark","本地补充备注");input.put("version",2);input.put("name","禁止改写来源名称");input.put("requestId",UUID.randomUUID().toString());assertThatThrownBy(()->inventory.save(id,false,input)).hasMessageContaining("来源系统同步维护");assertThat(inventory.detail(id,false)).containsEntry("name",actual.get("name")).containsEntry("remark","本地补充备注");}
 static void await(CountDownLatch latch){try{if(!latch.await(15,TimeUnit.SECONDS))throw new IllegalStateException("latch timeout");}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}}
}
